        mention.create()
    }
    const notify = mentionIds.filter((id) => !memberOf[id] || (memberOf[id].notificationLevelEnumId || 'CnlAll') !== 'CnlNone')
    if (notify.length) ec.service.sync().name('org.moqui.impl.ChatServices.notify#Mention').parameters({userIdList: notify,
        chatRoomId: chatRoomId, eventSeq: eventSeq, roomName: room.roomName || event.senderName || chatRoomId, authorUserId: sender,
        authorName: event.senderName || sender, bodyText: bodyText, roomUrl: roomUrl || null}).call()
}
ec.service.sync().name('org.moqui.impl.ChatServices.index#ChatEvent').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq}).call()
if (html) ec.service.sync().name('org.moqui.impl.ChatServices.queue#LinkPreviews').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    senderUserId: sender, body: html}).call()
// the counts of the members whose count it changes
const counted = new Set([sender].concat(mentionIds))
for (const row of memberRows) if (current(row) && row.userId !== sender && LEVEL_ALL(row)) counted.add(row.userId)
ec.service.sync().name('org.moqui.impl.ChatServices.publish#ChatCounts').parameter('userIdList', Array.from(counted)).call()
// the agent members: each gets the message to answer (the Assist port's entry point)
for (const row of memberRows) {
    if (row.roleEnumId !== 'CmrAgent' || !row.agentRef || row.leftDate || row.userId === sender) continue
    try {
        ec.message.pushErrors()
        ec.service.async().name('org.moqui.impl.ChatServices.deliver#AgentMessage').parameters({chatRoomId: chatRoomId,
            eventSeq: eventSeq, agentUserId: row.userId, agentRef: row.agentRef, senderUserId: sender, body: html,
            bodyText: bodyText, threadRootEventSeq: threadRoot}).call()
        if (ec.message.hasError()) ec.logger.warn(`Could not hand chat message ${chatRoomId}::${eventSeq} to agent ${row.userId}: ${ec.message.errorsString}`)
    } catch (err) {
