    }
}

const decode = (text) => String(text || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
        .replace(/&#x([0-9a-f]+);/gi, (m, hex) => String.fromCodePoint(parseInt(hex, 16))).replace(/&#(\d+);/g, (m, dec) => String.fromCodePoint(Number(dec)))
        .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
const toText = (html) => decode(String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|h[1-6]|blockquote|pre|div)>/gi, '\n')
        .replace(/<[^>]*>/g, '')).replace(/[ \t ]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim()
const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
editEventSeq = null; event = null
const me = ec.user.userId
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (!access.canPost) { ec.message.addError(access.isArchived ? 'The room is archived' : 'Join the room to post in it'); return }
const original = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!original || original.eventTypeEnumId !== 'CetMessage' || original.redactedDate) { ec.message.addError(`Message ${eventSeq} not found in the room`); return }
if (original.senderUserId !== me) { ec.message.addError('You may edit only your own messages'); return }
if (parse(original.contentJson).poll) { ec.message.addError('A poll is not edited: close it, or delete it and make another'); return }
const windowMinutes = Number(System.getProperty('chat_edit_window_minutes') || 1440)
if (windowMinutes > 0 && Number(ec.user.nowTimestamp) - Number(original.sentDate) > windowMinutes * 60000) {
    ec.message.addError('This message is too old to edit'); return }
const html = body ? String(body).trim() : ''
const bodyText = toText(html)
if (!bodyText && !/<img\b/i.test(html)) { ec.message.addError('Delete the message to remove its text'); return }
if (html.length > 65536) { ec.message.addError('The message is too long'); return }
const room = access.room
const memberRows = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).list())
const memberOf = {}
memberRows.forEach((row) => { memberOf[row.userId] = row })
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const mentionedAll = Array.from(new Set(Array.from(html.matchAll(/data-mention-id="([^"]*)"/g)).map((match) => decode(match[1]).trim())
        .filter((id) => id && id !== me)))
const mentioned = mentionedAll.filter((id) => id !== '@room')
let mentionIds = []
if (mentioned.length) {
    const users = new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', mentioned)
            .selectField('userId').disableAuthz().list()).map((row) => row.userId))
    // as send#Message: a user who is not a member of a record room counts when they may see the record
    const recordReader = (id) => room.visibilityEnumId === 'CrvRecord' && !!room.recordEntityName && !!room.recordId
            && ec.service.sync().name('org.moqui.impl.ChatServices.check#RecordVisible').disableAuthz()
                .parameters({recordEntityName: room.recordEntityName, recordId: room.recordId, userId: id}).call()?.recordVisible === true
    mentionIds = mentioned.filter((id) => users.has(id) && ((memberOf[id] && (!memberOf[id].leftDate || isDirect))
            || room.visibilityEnumId === 'CrvUsers' || recordReader(id)))
}
