        .disableAuthz().call()?.anyExternal !== false
const rooms = new Set()
for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', rows.map((row) => row.chatRoomId))
        .condition('archivedDate', null).selectField('chatRoomId').selectField('roomTypeEnumId').selectField('visibilityEnumId')
        .selectField('recordEntityName').list()) {
    if (external && (room.roomTypeEnumId === 'CrtRecord' || room.visibilityEnumId === 'CrvRecord' || room.recordEntityName)) continue
    rooms.add(room.chatRoomId)
}
// the unread messages and the mentions of every room in one query each (ChatMemberUnread, ChatMemberMentions)
const unreadOf = {}, mentionsOf = {}
for (const count of ec.entity.find('moqui.chat.ChatMemberUnread').condition('userId', userId).condition('leftDate', null)
        .condition('redactedDate', null).selectField('chatRoomId').selectField('unreadCount').list())
    unreadOf[count.chatRoomId] = Number(count.unreadCount || 0)
for (const count of ec.entity.find('moqui.chat.ChatMemberMentions').condition('userId', userId).condition('leftDate', null)
        .selectField('chatRoomId').selectField('mentionCount').list())
    mentionsOf[count.chatRoomId] = Number(count.mentionCount || 0)
for (const row of rows) {
    if (!rooms.has(row.chatRoomId)) continue
    const roomUnread = unreadOf[row.chatRoomId] || 0
    const roomMentions = mentionsOf[row.chatRoomId] || 0
    if (!roomUnread && !roomMentions) continue
    const level = row.notificationLevelEnumId || 'CnlAll'
    const effective = level === 'CnlNone' ? 'CnlNone' : (row.isMuted === 'Y' ? 'CnlMentions' : level)
    const counted = effective === 'CnlAll' ? roomUnread : (effective === 'CnlMentions' ? roomMentions : 0)
    roomCounts[row.chatRoomId] = {unread: roomUnread, mentions: roomMentions, counted: counted}
    if (effective === 'CnlAll') unread += roomUnread
    if (effective !== 'CnlNone') mentions += roomMentions
    total += counted
    if (counted > 0) unreadRoomCount++
}

