        .disableAuthz().list())
for (const room of rooms) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.clean#RoomRetention').parameter('chatRoomId', room.chatRoomId)
                .requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) {
            failedCount++
            ec.logger.error(`Could not apply the retention of chat room ${room.chatRoomId}: ${ec.message.errorsString}`)
        } else {
            roomCount++
            deletedCount += Number((out && out.deletedCount) || 0)
        }
    } catch (err) {
        failedCount++
        ec.logger.error(`Could not apply the retention of chat room ${room.chatRoomId}: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (deletedCount || failedCount) ec.logger.info(`Chat retention: ${deletedCount} events deleted in ${roomCount} rooms, ${failedCount} rooms failed`)

const snippetOf = (text, attachments) => {
    const shown = String(text || '').replace(/\s+/g, ' ').trim()
    if (shown) return shown.length > 140 ? shown.slice(0, 139) + '…' : shown
    const files = (attachments || []).map((file) => file.fileName).filter((name) => name)
    return files.length ? '📎 ' + files.join(', ') : ''
}
const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
deletedCount = 0
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).forUpdate(true).one()
if (!room || !(Number(room.retentionDays) > 0)) return
const before = Number(ec.user.nowTimestamp) - Number(room.retentionDays) * 86400000
const old = Array.from(ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('sentDate', 'less', String(before))
        .selectField('eventSeq').selectField('eventTypeEnumId').orderBy('eventSeq').limit(Math.max(1, limit)).list())
if (!old.length) return
const seqs = old.map((row) => Number(row.eventSeq))
const counted = new Set()
for (const row of old) {
    if (row.eventTypeEnumId !== 'CetMessage') continue
    const cleared = ec.service.sync().name('org.moqui.impl.ChatServices.clear#MessageContent').parameters({chatRoomId: chatRoomId,
        eventSeq: row.eventSeq}).call()
    if (ec.message.hasError()) return
    for (const id of (cleared && cleared.mentionedUserIdList) || []) counted.add(id)
}
// the edits, reactions and redactions of the events deleted, then the events, a chunk at a time
const doomed = new Set(seqs)
for (let start = 0; start < seqs.length; start += 500) {
    const chunk = seqs.slice(start, start + 500)
    for (const field of ['editsEventSeq', 'relatesToEventSeq'])
        for (const row of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition(field, 'in', chunk)
                .selectField('eventSeq').list()) doomed.add(Number(row.eventSeq))
}
const all = Array.from(doomed).sort((left, right) => left - right)
for (let start = 0; start < all.length; start += 500)
    deletedCount += ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
            .condition('eventSeq', 'in', all.slice(start, start + 500)).deleteAll()
// the room's last message is the last one that stands
if (room.lastMessageSeq != null && doomed.has(Number(room.lastMessageSeq))) {
    const last = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventTypeEnumId', 'CetMessage')
            .condition('threadRootEventSeq', null).condition('redactedDate', null).orderBy('-eventSeq').limit(1).list()
    const row = last.length ? last[0] : null
    room.setFields({lastMessageSeq: row ? row.eventSeq : null, lastMessageUserId: row ? row.senderUserId : null,
        lastMessageDate: row ? row.sentDate : null, lastMessageSnippet: row ? (snippetOf(row.bodyText, parse(row.contentJson).attachments) || null) : null}, true, null, null)
    room.update()
}
for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null)
        .condition('lastReadEventSeq', 'less', all[all.length - 1]).selectField('userId').list()) counted.add(row.userId)
if (counted.size) ec.service.sync().name('org.moqui.impl.ChatServices.publish#ChatCounts').parameter('userIdList', Array.from(counted)).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
fileList = []; nextBeforeEventSeq = null
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const size = Math.max(1, Math.min(100, Number(limit) || 30))
const cf = ec.entity.conditionFactory
let find = ec.entity.find('moqui.chat.ChatAttachment').condition('chatRoomId', chatRoomId).condition('eventSeq', 'not-equals', null)
if (beforeEventSeq != null) find = find.condition('eventSeq', 'less', beforeEventSeq)
if (contentTypePrefix) find = find.condition(cf.makeCondition('contentType', 'like', String(contentTypePrefix).replace(/[%_]/g, '') + '%').ignoreCase())
const text = String(searchText || '').trim().replace(/[%_]/g, '')
if (text) find = find.condition(cf.makeCondition('fileName', 'like', '%' + text + '%').ignoreCase())
let rows = Array.from(find.orderBy('-eventSeq').orderBy('attachmentSeq').limit(size + 1).list())
if (rows.length > size) {
    rows = rows.slice(0, size)
    // the page ends at a whole message: the files of its last message come on the next page, unless that is all of it
    const lastSeq = Number(rows[rows.length - 1].eventSeq)
    const whole = rows.filter((row) => Number(row.eventSeq) !== lastSeq)
    if (whole.length) rows = whole
    nextBeforeEventSeq = Number(rows[rows.length - 1].eventSeq)
}
if (!rows.length) return
const events = {}
for (const row of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
        .condition('eventSeq', 'in', Array.from(new Set(rows.map((row) => Number(row.eventSeq))))).list()) events[Number(row.eventSeq)] = row
const userIds = Array.from(new Set(Object.values(events).map((row) => row.senderUserId).filter((id) => id)))
const names = {}
if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
for (const row of rows) {
    const event = events[Number(row.eventSeq)]
    if (!event || event.redactedDate) continue
    fileList.push({chatAttachmentId: row.chatAttachmentId, eventSeq: Number(row.eventSeq), attachmentSeq: Number(row.attachmentSeq || 0),
        fileName: row.fileName ?? null, contentType: row.contentType ?? null, fileSize: row.fileSize != null ? Number(row.fileSize) : null,
        senderUserId: event.senderUserId ?? null, senderName: event.senderUserId ? names[event.senderUserId] || event.senderUserId : null,
        sentDate: toMillis(event.sentDate), threadRootEventSeq: event.threadRootEventSeq != null ? Number(event.threadRootEventSeq) : null})
}

const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
eventSeq = null; event = null; duplicate = false
const me = ec.user.userId
const asked = String(question || '').replace(/\s+/g, ' ').trim()
if (!asked) { ec.message.addError('A poll needs a question'); return }
if (asked.length > 500) { ec.message.addError('The question is too long'); return }
const options = []
for (const option of Array.from(optionList || [])) {
    const shown = String(option ?? '').replace(/\s+/g, ' ').trim()
    if (!shown) continue
    if (shown.length > 200) { ec.message.addError('An option is up to 200 characters'); return }
    if (options.some((other) => other.toLowerCase() === shown.toLowerCase())) { ec.message.addError(`The option ${shown} is there twice`); return }
    options.push(shown)
}
if (options.length < 2 || options.length > 10) { ec.message.addError('A poll has 2 to 10 options'); return }
const closes = closesDate != null ? Number(closesDate) : null
if (closes != null && closes <= Number(ec.user.nowTimestamp)) { ec.message.addError('A poll closes later than now'); return }
const sent = ec.service.sync().name('org.moqui.impl.ChatServices.send#Message').parameters({chatRoomId: chatRoomId,
    body: '<p>' + escape(asked) + '</p>', threadRootEventSeq: threadRootEventSeq ?? null, clientRef: clientRef || null, roomUrl: roomUrl || null}).call()
if (ec.message.hasError()) return
eventSeq = sent.eventSeq
event = sent.event
if (sent.duplicate) { duplicate = true; return }
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
const content = JSON.parse(row.contentJson || '{}')
content.poll = {question: asked}
row.set('contentJson', JSON.stringify(content))
row.update()
const poll = ec.entity.makeValue('moqui.chat.ChatPoll')
poll.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, question: asked, isAnonymous: anonymous ? 'Y' : 'N', allowMultiple: multiple ? 'Y' : 'N',
    closesDate: closesDate ?? null, createdByUserId: me, voterCount: 0}, true, null, null)
poll.create()
options.forEach((text, index) => {
    const option = ec.entity.makeValue('moqui.chat.ChatPollOption')
    option.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, optionSeq: index + 1, optionText: text, voteCount: 0}, true, null, null)
    option.create()
})
const states = ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
    eventSeqList: [eventSeq]}).call().pollMap || {}
const shared = ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
    eventSeqList: [eventSeq], shared: true}).call().pollMap || {}
event = Object.assign({}, event, {poll: states[eventSeq] || null})
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {poll: shared[eventSeq] || null}}).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
pollMap = {}
const seqs = Array.from(new Set(Array.from(eventSeqList || []).map(Number).filter((seq) => !Number.isNaN(seq))))
if (!seqs.length) return
const me = ec.user.userId
const now = Number(ec.user.nowTimestamp)
const polls = Array.from(ec.entity.find('moqui.chat.ChatPoll').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs).list())
if (!polls.length) return
const options = {}, votes = {}
for (const row of ec.entity.find('moqui.chat.ChatPollOption').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs)
        .orderBy('optionSeq').list()) (options[Number(row.eventSeq)] = options[Number(row.eventSeq)] || []).push(row)
for (const row of ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs)
        .orderBy('votedDate').list()) (votes[Number(row.eventSeq)] = votes[Number(row.eventSeq)] || []).push(row)
for (const poll of polls) {
    const seq = Number(poll.eventSeq)
    const anonymous = poll.isAnonymous === 'Y'
    const cast = votes[seq] || []
    const closesAt = toMillis(poll.closesDate)
    const state = {question: poll.question ?? null, anonymous: anonymous, multiple: poll.allowMultiple === 'Y', closesDate: closesAt,
        closedDate: toMillis(poll.closedDate), closed: !!poll.closedDate || (closesAt != null && closesAt <= now),
        createdByUserId: poll.createdByUserId ?? null, voterCount: Number(poll.voterCount || 0), totalVotes: 0,
        options: (options[seq] || []).map((row) => {
            const id = Number(row.optionSeq)
            const option = {id: id, text: row.optionText ?? '', voteCount: Number(row.voteCount || 0),
                voterIds: anonymous ? [] : cast.filter((vote) => Number(vote.optionSeq) === id).map((vote) => vote.userId)}
            if (!shared) option.mine = cast.some((vote) => Number(vote.optionSeq) === id && vote.userId === me)
            return option
        })}
    state.totalVotes = state.options.reduce((sum, option) => sum + option.voteCount, 0)
    if (!shared) state.mine = cast.filter((vote) => vote.userId === me).map((vote) => Number(vote.optionSeq))
    pollMap[seq] = state
}

poll = null
const me = ec.user.userId
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (!access.canPost) { ec.message.addError(access.isArchived ? 'The room is archived' : 'Join the room to vote'); return }
const row = ec.entity.find('moqui.chat.ChatPoll').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!row) { ec.message.addError(`Poll ${eventSeq} not found in the room`); return }
const now = Number(ec.user.nowTimestamp)
if (row.closedDate || (row.closesDate != null && Number(row.closesDate) <= now)) { ec.message.addError('The poll is closed'); return }
const chosen = Array.from(new Set(Array.from(optionIdList || []).map((id) => Number(id)).filter((id) => !Number.isNaN(id))))
if (chosen.length > 1 && row.allowMultiple !== 'Y') { ec.message.addError('Choose one option'); return }
const options = Array.from(ec.entity.find('moqui.chat.ChatPollOption').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).list())
const byId = {}
options.forEach((option) => { byId[Number(option.optionSeq)] = option })
const unknown = chosen.filter((id) => !byId[id])
if (unknown.length) { ec.message.addError(`Option ${unknown.join(', ')} not found in the poll`); return }
const before = Array.from(ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
        .condition('userId', me).list()).map((vote) => Number(vote.optionSeq))
const same = before.length === chosen.length && before.every((id) => chosen.includes(id))
if (!same) {
    ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).condition('userId', me).deleteAll()
    for (const id of before) if (byId[id]) byId[id].set('voteCount', Math.max(0, Number(byId[id].voteCount || 0) - 1))
    for (const id of chosen) {
        const vote = ec.entity.makeValue('moqui.chat.ChatPollVote')
        vote.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, userId: me, optionSeq: id, votedDate: ec.user.nowTimestamp}, true, null, null)
        vote.create()
        byId[id].set('voteCount', Number(byId[id].voteCount || 0) + 1)
    }
    for (const option of options) if (before.includes(Number(option.optionSeq)) || chosen.includes(Number(option.optionSeq))) option.update()
    const voters = new Set(Array.from(ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
            .selectField('userId').list()).map((vote) => vote.userId))
    row.set('voterCount', voters.size)
    row.update()
}
poll = (ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId, eventSeqList: [eventSeq]})
        .call().pollMap || {})[eventSeq] || null
if (!same) ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {poll: (ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
        eventSeqList: [eventSeq], shared: true}).call().pollMap || {})[eventSeq] || null}}).call()

poll = null
const me = ec.user.userId
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatPoll').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!row) { ec.message.addError(`Poll ${eventSeq} not found in the room`); return }
if (!(row.createdByUserId === me && access.isMember) && !access.canModerate) { ec.message.addError('Only the poll\'s creator or a moderator may close it'); return }
if (!row.closedDate) {
    row.set('closedDate', ec.user.nowTimestamp)
    row.set('closedByUserId', me)
    row.update()
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
        fields: {poll: (ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
            eventSeqList: [eventSeq], shared: true}).call().pollMap || {})[eventSeq] || null}}).call()
}
poll = (ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId, eventSeqList: [eventSeq]})
        .call().pollMap || {})[eventSeq] || null

eventSeq = null
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('An agent card is sent by the agent runtime'); return }
const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const kind = String(assist.kind || '')
if (!['approval', 'question', 'reply'].includes(kind)) { ec.message.addError(`An agent card is an approval, a question or a reply, not ${kind}`); return }
const html = body ? String(body) : '<p>' + escape(bodyText || assist.summary || assist.title || kind) + '</p>'
const sent = ec.service.sync().name('org.moqui.impl.ChatServices.send#Message').parameters({chatRoomId: chatRoomId,
    senderUserId: senderUserId, body: html, threadRootEventSeq: threadRootEventSeq ?? null}).call()
if (ec.message.hasError()) return
eventSeq = sent.eventSeq
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
const content = JSON.parse(row.contentJson || '{}')
content.assist = Object.assign({}, assist, {kind: kind, state: assist.state || (kind === 'reply' ? 'done' : 'pending')})
row.set('contentJson', JSON.stringify(content))
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {assist: content.assist}}).call()

if (String(System.getProperty('chat_link_previews') || '').trim() === 'false') return
if (!/https?:\/\//i.test(String(body || ''))) return
if (senderUserId) {
    const pref = ec.entity.find('moqui.security.UserPreference').condition('userId', senderUserId).condition('preferenceKey', 'CHAT_LINK_PREVIEWS')
            .disableAuthz().one()
    const value = pref ? String(pref.preferenceValue || '').trim() : ''
    if (value === 'N' || value === 'false') return
}
try {
    ec.service.special().name('org.moqui.impl.ChatServices.fetch#LinkPreviews').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq}).registerOnCommit()
} catch (err) {
    ec.logger.error(`Could not queue the link previews of chat message ${chatRoomId}::${eventSeq}: ${err && err.message ? err.message : err}`)
}

const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
linkPreviews = []
ec.artifactExecution.disableAuthz()
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
if (!row || row.eventTypeEnumId !== 'CetMessage' || row.redactedDate || parse(row.linkPreviewJson).removed) return
let body = parse(row.contentJson).body
if (row.lastEditEventSeq != null) {
    const edit = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', row.lastEditEventSeq).one()
    if (edit && parse(edit.contentJson).body != null) body = parse(edit.contentJson).body
}
const urls = ec.service.sync().name('org.moqui.impl.ChatServices.extract#LinkUrls').parameter('body', body || '').call().urlList || []
for (const link of urls) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#LinkPreview').parameters({url: link.url, urlHash: link.urlHash}).call()
        if (ec.message.hasError()) ec.logger.warn(`Could not preview ${link.url} of chat message ${chatRoomId}::${eventSeq}: ${ec.message.errorsString}`)
        else if (out && out.preview) linkPreviews.push(out.preview)
    } catch (err) {
        ec.logger.warn(`Could not preview ${link.url} of chat message ${chatRoomId}::${eventSeq}: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const next = linkPreviews.length ? JSON.stringify(linkPreviews) : null
if ((row.linkPreviewJson || null) === next) return
row.set('linkPreviewJson', next)
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {linkPreviews: linkPreviews}}).call()

preview = null
const now = Number(ec.user.nowTimestamp)
const shown = (row) => row && row.failed !== 'Y' && row.title ? {url: url, title: row.title, description: row.description || null,
    siteName: row.siteName || null} : null
let row = ec.entity.find('moqui.chat.ChatLinkPreview').condition('urlHash', urlHash).disableAuthz().one()
if (row && row.url === url && row.fetchedDate != null && now - Number(row.fetchedDate) < (row.failed === 'Y' ? 3600000 : 86400000)) {
    preview = shown(row)
    return
}
const page = ec.service.sync().name('org.moqui.impl.ChatServices.fetch#LinkPage').parameter('url', url).call()
const fields = {url: url, title: page.ok && page.title ? page.title : null, description: page.ok && page.description ? page.description : null,
    siteName: page.ok && page.siteName ? page.siteName : null, failed: page.ok ? 'N' : 'Y', fetchedDate: ec.user.nowTimestamp}
if (row) { row.setFields(fields, true, null, null); row.update() }
else {
    row = ec.entity.makeValue('moqui.chat.ChatLinkPreview')
    row.setFields(Object.assign({urlHash: urlHash}, fields), true, null, null)
    row.create()
}
preview = shown(row)

const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!row || row.eventTypeEnumId !== 'CetMessage' || row.redactedDate) { ec.message.addError(`Message ${eventSeq} not found in the room`); return }
if (row.senderUserId !== ec.user.userId) { ec.message.addError('Only the sender removes the previews of a message'); return }
row.set('linkPreviewJson', '{"removed":true}')
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {linkPreviews: []}}).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const cf = ec.entity.conditionFactory
eventList = []; total = 0
const me = ec.user.userId
const text = String(searchText || '').trim()
if (!me || !text) return
const size = Math.max(1, Math.min(100, Number(limit) || 20))
const offset = Math.max(0, Number(pageIndex) || 0) * size
let myRooms = []
let includePublic = true
if (chatRoomId) {
    const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
    if (ec.message.hasError()) return
    if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
    myRooms = [chatRoomId]
    includePublic = false
} else {
    const directOrCurrent = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).selectField('chatRoomId')
            .selectField('leftDate').list())
    const ids = directOrCurrent.map((row) => row.chatRoomId)
    const directIds = new Set(ids.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', ids)
            .condition('roomTypeEnumId', 'CrtDirect').selectField('chatRoomId').list()).map((row) => row.chatRoomId) : [])
    myRooms = directOrCurrent.filter((row) => !row.leftDate || directIds.has(row.chatRoomId)).map((row) => row.chatRoomId)
    // an external user (EXTERNAL_USER; a failed check counts as external): no record room, no public room not joined
    if (ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [me]).disableAuthz()
            .call()?.anyExternal !== false) {
        includePublic = false
        const recordIds = new Set(myRooms.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', myRooms)
                .selectField('chatRoomId').selectField('roomTypeEnumId').selectField('visibilityEnumId').selectField('recordEntityName').list())
                .filter((row) => row.roomTypeEnumId === 'CrtRecord' || row.visibilityEnumId === 'CrvRecord' || row.recordEntityName)
                .map((row) => row.chatRoomId) : [])
        myRooms = myRooms.filter((id) => !recordIds.has(id))
    }
}
const names = {}
const roomNames = {}
const finish = () => {
    const userIds = Array.from(new Set(eventList.map((item) => item.senderUserId).filter((id) => id)))
    if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
            .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
        names[account.userId] = account.userFullName || account.username || account.userId
    const roomIds = Array.from(new Set(eventList.map((item) => item.chatRoomId)))
    if (roomIds.length) for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', roomIds)
            .selectField('chatRoomId').selectField('roomName').list()) roomNames[room.chatRoomId] = room.roomName
    for (const item of eventList) {
        if (!item.senderName && item.senderUserId) item.senderName = names[item.senderUserId] || item.senderUserId
        if (!item.roomName) item.roomName = roomNames[item.chatRoomId] || null
    }
}
if (ec.search.isAvailable() && ec.search.indexExists({documentType: 'MoquiChatEvent'})) {
    const allowed = []
    if (myRooms.length) allowed.push({field: {name: 'chatRoomId', op: 'in', values: myRooms}})
    if (includePublic) allowed.push({field: {name: 'roomVisibilityEnumId', op: 'eq', value: 'CrvUsers'}})
    if (!allowed.length) return
    let result
    try {
        result = ec.search.search({documentType: 'MoquiChatEvent', query: {text: {terms: text, fields: 'all', match: 'prefix'}},
            filter: {bool: {any: allowed}}, offset: offset, limit: size, highlight: ['bodyText']})
    } catch (err) {
        ec.message.addMessage(`Invalid search: ${text} (${err && err.message ? err.message : err})`, 'danger')
        return
    }
    total = Number(result.total || 0)
    for (const hit of result.hits) {
        const body = hit.body || {}
        const highlights = hit.highlights && hit.highlights.bodyText
        const snippet = String(body.bodyText || '').replace(/\s+/g, ' ').trim()
        eventList.push({chatRoomId: body.chatRoomId, eventSeq: Number(body.eventSeq), roomName: body.roomName ?? null,
            senderUserId: body.senderUserId ?? null, senderName: body.senderName ?? null, sentDate: toMillis(body.sentDate),
            snippet: snippet.length > 160 ? snippet.slice(0, 159) + '…' : snippet,
            highlight: Array.isArray(highlights) ? highlights[0] : (highlights || null)})
    }
    finish()
    return
}
// without search: the text of the messages, in the rooms the user may read
let roomIds = myRooms.slice()
if (includePublic) for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('visibilityEnumId', 'CrvUsers')
        .selectField('chatRoomId').list()) if (!roomIds.includes(room.chatRoomId)) roomIds.push(room.chatRoomId)
if (!roomIds.length) return
const words = text.split(/\s+/).filter((word) => word)
const find = () => {
    let found = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', 'in', roomIds).condition('eventTypeEnumId', 'CetMessage')
            .condition('redactedDate', null)
    for (const word of words) found = found.condition(cf.makeCondition('bodyText', 'like', `%${word}%`, false, true))
    return found
}
total = find().count()
for (const row of find().orderBy('-sentDate').offset(offset).limit(size).list()) {
    const snippet = String(row.bodyText || '').replace(/\s+/g, ' ').trim()
    eventList.push({chatRoomId: row.chatRoomId, eventSeq: Number(row.eventSeq), roomName: null, senderUserId: row.senderUserId ?? null,
        senderName: null, sentDate: toMillis(row.sentDate), snippet: snippet.length > 160 ? snippet.slice(0, 159) + '…' : snippet, highlight: null})
}
finish()

if (!agentRef) {
    const row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', agentUserId).disableAuthz().one()
    agentRef = row ? row.agentRef : null
}
if (!agentRef) { ec.logger.info(`Chat agent ${agentUserId} of room ${chatRoomId} has no agentRef; no agent runs in the framework`); return }
ec.message.pushErrors()
try {
    ec.service.sync().name(agentRef).parameters({chatRoomId: chatRoomId, eventSeq: eventSeq, agentUserId: agentUserId,
        senderUserId: senderUserId, body: body, bodyText: bodyText, threadRootEventSeq: threadRootEventSeq}).call()
    if (ec.message.hasError()) ec.logger.error(`Chat agent service ${agentRef} failed for ${chatRoomId}::${eventSeq}: ${ec.message.errorsString}`)
} catch (err) {
    ec.logger.error(`Chat agent service ${agentRef} failed for ${chatRoomId}::${eventSeq}: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const OFFLINE_AFTER = 3 * 60000
const CODES = {UpsOnline: 'online', UpsAway: 'away', UpsDnd: 'dnd', UpsInvisible: 'invisible'}
statusMap = {}; myStatus = null
const me = ec.user.userId
let ids = Array.from(new Set((userIdList || []).map((id) => String(id || '').trim()).filter((id) => id))).slice(0, 500)
// an external current user (EXTERNAL_USER; a failed check counts as external) sees only their own status
if (me && ids.some((id) => id !== me) && ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers')
        .parameter('userIdList', [me]).disableAuthz().call()?.anyExternal !== false) ids = ids.filter((id) => id === me)
if (!ids.length) return
const now = Number(ec.user.nowTimestamp)
const rows = {}
for (const row of ec.entity.find('moqui.security.UserStatus').condition('userId', 'in', ids).disableAuthz().list()) rows[row.userId] = row
const awayMinutes = {}
for (const pref of ec.entity.find('moqui.security.UserPreference').condition('userId', 'in', ids)
        .condition('preferenceKey', 'CHAT_AUTO_AWAY_MINUTES').disableAuthz().list()) {
    const minutes = Number(pref.preferenceValue)
    if (minutes > 0) awayMinutes[pref.userId] = minutes
}
for (const id of ids) {
    const row = rows[id]
    const minutes = awayMinutes[id] || 10
    const expired = row && row.clearAtDate && toMillis(row.clearAtDate) <= now
    const chosen = row && !expired ? (row.statusEnumId || 'UpsOnline') : 'UpsOnline'
    const seen = row ? toMillis(row.lastSeenDate) : null
    const active = row ? toMillis(row.lastActiveDate) : null
    let presence
    if (!seen || now - seen > OFFLINE_AFTER || chosen === 'UpsInvisible') presence = 'offline'
    else if (chosen === 'UpsDnd') presence = 'dnd'
    else if (chosen === 'UpsAway') presence = 'away'
    else if (!active || now - active >= minutes * 60000) presence = 'away'
    else presence = 'online'
    const item = {userId: id, presence: presence, statusText: row && !expired ? row.statusText ?? null : null,
        emoji: row && !expired ? row.emoji ?? null : null, clearAtDate: row && !expired ? toMillis(row.clearAtDate) : null,
        inCall: !!row && row.inCall === 'Y', lastActiveDate: active}
    statusMap[id] = item
    if (id === me) myStatus = Object.assign({}, item, {statusEnumId: chosen, status: CODES[chosen] || 'online', autoAwayMinutes: minutes,
        connected: !!seen && now - seen <= OFFLINE_AFTER})
}

published = false
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [userId]).call()
const item = out && out.statusMap ? out.statusMap[userId] : null
if (!item) return
const row = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).disableAuthz().one()
if (!force && row && row.lastPresence === item.presence) return
if (row) { row.set('lastPresence', item.presence); row.update() }
const message = {userId: userId, presence: item.presence, statusText: item.statusText, emoji: item.emoji,
    clearAtDate: item.clearAtDate, inCall: item.inCall}
const roomIds = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', userId).condition('leftDate', null)
        .selectField('chatRoomId').disableAuthz().list()).map((member) => member.chatRoomId)
const others = new Set()
if (roomIds.length) for (const member of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', roomIds)
        .condition('leftDate', null).selectField('userId').disableAuthz().list()) if (member.userId !== userId) others.add(member.userId)
const recipients = Array.from(others).slice(0, 2000)
if (recipients.length) ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'userStatus',
    userIdList: recipients, message: message}).call()
const CODES = {UpsOnline: 'online', UpsAway: 'away', UpsDnd: 'dnd', UpsInvisible: 'invisible'}
const expired = row && row.clearAtDate && Number(row.clearAtDate) <= Number(ec.user.nowTimestamp)
ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'userStatus', userIdList: [userId],
    message: Object.assign({}, message, {self: true, status: row && !expired ? CODES[row.statusEnumId] || 'online' : 'online'})}).call()
published = true

const STATUSES = {online: 'UpsOnline', away: 'UpsAway', dnd: 'UpsDnd', invisible: 'UpsInvisible'}
myStatus = null
const me = ec.user.userId
if (!userId) userId = me
if (!userId) { ec.message.addError('No user to set the status of'); return }
if (userId !== me && !ec.artifactExecution.authzDisabled()) { ec.message.addError('You set only your own status'); return }
const chosen = statusEnumId || status
const statusId = chosen ? (STATUSES[chosen] || chosen) : null
if (statusId && !Object.values(STATUSES).includes(statusId)) { ec.message.addError(`Unknown status ${chosen}`); return }
const now = ec.user.nowTimestamp
let row = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).forUpdate(true).one()
const created = !row
if (created) {
    row = ec.entity.makeValue('moqui.security.UserStatus')
    row.setFields({userId: userId, statusEnumId: 'UpsOnline'}, true, null, null)
}
if (statusId) row.set('statusEnumId', statusId)
if (clearStatus) {
    row.set('statusText', null); row.set('emoji', null); row.set('clearAtDate', null)
} else {
    if (statusText != null) {
        const text = String(statusText).trim()
        if (Array.from(text).length > 100) { ec.message.addError('A status is up to 100 characters'); return }
        row.set('statusText', text || null)
    }
    if (emoji != null) {
        const shown = String(emoji).trim()
        if (Array.from(shown).length > 16 || /[<>]/.test(shown)) { ec.message.addError('An emoji is a few characters'); return }
        row.set('emoji', shown || null)
    }
    if (clearAfterMinutes != null) row.set('clearAtDate', clearAfterMinutes > 0 ? String(Number(now) + clearAfterMinutes * 60000) : null)
    else if (clearAtDate != null) row.set('clearAtDate', clearAtDate)
}
row.set('statusSetDate', now)
if (userId === me) { row.set('lastSeenDate', now); row.set('lastActiveDate', now) }
if (created) row.create(); else row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').parameters({userId: userId, force: true}).call()
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [userId]).call()
myStatus = out.myStatus || (out.statusMap ? out.statusMap[userId] : null)

myStatus = null
const me = ec.user.userId
if (!me) return
const now = Number(ec.user.nowTimestamp)
let row = ec.entity.find('moqui.security.UserStatus').condition('userId', me).forUpdate(true).one()
const created = !row
if (created) {
    row = ec.entity.makeValue('moqui.security.UserStatus')
    row.setFields({userId: me, statusEnumId: 'UpsOnline'}, true, null, null)
}
row.set('lastSeenDate', String(now))
const before = row.lastActiveDate != null ? Number(row.lastActiveDate) : 0
let lastActive = null
if (idleSeconds != null) lastActive = now - Math.max(0, idleSeconds) * 1000
else if (active !== false) lastActive = now
if (lastActive != null && lastActive > before) row.set('lastActiveDate', String(lastActive))
if (created) row.create(); else row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').parameter('userId', me).call()
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [me]).call()
myStatus = out.myStatus

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
published = false
if (userId !== ec.user.userId && !ec.artifactExecution.authzDisabled()) { ec.message.addError('You disconnect only yourself'); return }
const row = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).forUpdate(true).disableAuthz().one()
if (!row) return
const offlineAt = Number(ec.user.nowTimestamp) - 3 * 60000 - 1000
const seen = toMillis(row.lastSeenDate)
if (seen == null || seen > offlineAt) { row.set('lastSeenDate', String(offlineAt)); row.update() }
const out = ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').parameter('userId', userId).call()
published = !!(out && out.published)

clearedCount = 0; publishedCount = 0
const now = Number(ec.user.nowTimestamp)
const expired = Array.from(ec.entity.find('moqui.security.UserStatus').condition('clearAtDate', 'less-equals', String(now)).disableAuthz().list())
const users = new Set()
for (const row of expired) {
    try {
        row.setFields({statusText: null, emoji: null, clearAtDate: null, statusEnumId: 'UpsOnline'}, true, null, null)
        row.update()
        clearedCount++
        users.add(row.userId)
    } catch (err) {
        ec.logger.error(`Could not clear the status of user ${row.userId}: ${err && err.message ? err.message : err}`)
    }
}
for (const row of ec.entity.find('moqui.security.UserStatus').condition('lastPresence', 'in', ['online', 'away', 'dnd'])
        .selectField('userId').disableAuthz().list()) users.add(row.userId)
const forced = new Set(expired.map((row) => row.userId))
for (const userId of users) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').disableAuthz()
                .parameters({userId: userId, force: forced.has(userId)}).call()
        if (ec.message.hasError()) ec.logger.error(`Could not publish the status of user ${userId}: ${ec.message.errorsString}`)
        else if (out && out.published) publishedCount++
    } catch (err) {
        ec.logger.error(`Could not publish the status of user ${userId}: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
